cases.judge_raw:
{
  "claims": [
    {
      "claim": "RC-S200 续航变短、一次扫不完就没电的问题，适用[1]中“RC-S200 续航变短排查”流程。",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "引用格式标注，非事实性元评论。"
    },
    {
      "claim": "按顺序执行以下步骤，任一步骤解决后即可结束排查。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]对该流程导语有原文。"
    },
    {
      "claim": "在 App 查看是否长期使用最高吸力档",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1明确指示此操作。"
    },
    {
      "claim": "高档位与地毯环境耗电明显加快",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1直接给出了该因果解释。"
    },
    {
      "claim": "改用标准档对比一次续航",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1要求改用标准档对比续航。"
    },
    {
      "claim": "让机器清扫至自动回充",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤2描述此操作。"
    },
    {
      "claim": "然后一次性充到指示灯显示充满",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤2要求一次性充到充满指示灯。"
    },
    {
      "claim": "重复一轮以校准电量显示",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤2说明重复一轮以校准电量。"
    },
    {
      "claim": "触点脏污会导致未充满即中断",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3开头即为此因果说明。"
    },
    {
      "claim": "关机后用干燥软布轻擦主机极片与基站弹片",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3给出了清洁触点的具体操作。"
    },
    {
      "claim": "禁止使用湿布或金属工具接触触点",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3安全提示原文禁止此行为。"
    },
    {
      "claim": "使用超过两年且校准后续航仍明显缩短的，属电池自然衰减",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤4直接给出该判断。"
    },
    {
      "claim": "应结束自助排查并联系售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于'请联系售后'类兜底话术。"
    },
    {
      "claim": "电池不可自行拆卸或更换，必须由官方售后处理",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤4安全提示明确说明。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在的，请停止自助排查并联系官方售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于'请联系售后'类兜底话术。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "步骤1（检查基站供电）：确认基站电源接通、屏幕指示正常，断电重启基站一次",
      "verdict": "supported",
      "evidence_index": [2],
      "reason": "与片段[2]步骤1完全一致"
    },
    {
      "claim": "步骤2（清理基站周边）：基站前方1.5米、两侧0.5米不放置杂物，移除强反光的镜面和金属踢脚线遮挡",
      "verdict": "supported",
      "evidence_index": [2],
      "reason": "与片段[2]步骤2完全一致"
    },
    {
      "claim": "步骤3（清洁回充信号窗）：用干布擦拭基站正面信号发射窗与机身回充接收窗",
      "verdict": "supported",
      "evidence_index": [2],
      "reason": "与片段[2]步骤3完全一致"
    },
    {
      "claim": "步骤4（近距离重试）：机器放到基站前1米按回充键重试，仍失败结束自助排查",
      "verdict": "supported",
      "evidence_index": [2],
      "reason": "与片段[2]步骤4完全一致"
    },
    {
      "claim": "若上述步骤全部执行后问题仍存在，请停止自助排查并联系官方售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "联系售后类兜底话术，非事实性论断"
    },
    {
      "claim": "片段里没有“E10/E11 错误码与无法回充直接关联”的说法",
      "verdict": "supported",
      "evidence_index": [1, 2],
      "reason": "片段[1]仅描述E10/E11含义，片段[2]为回充排查，均未提及二者关联"
    },
    {
      "claim": "错误码 E11 明确指向“基站通讯失败”",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]明确标注E11为基站通讯失败"
    },
    {
      "claim": "错误码 E11 的自助排查要求“清洁充电触点与信号窗，重启机器与基站”",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]原句为‘清洁充电触点与信号窗，重启机器与基站’"
    },
    {
      "claim": "片段里没有“水路异常（E07）或配网失败（App 配网）与无法回充相关”的说法",
      "verdict": "supported",
      "evidence_index": [4, 5],
      "reason": "片段[4]为E07水路异常排查，片段[5]为App配网失败排查，均未提及与无法回充相关"
    },
    {
      "claim": "片段里没有“无法开机排查步骤适用于无法回充”的说法",
      "verdict": "supported",
      "evidence_index": [3],
      "reason": "片段[3]为无法开机排查，未声明适用于无法回充"
    },
    {
      "claim": "片段步骤1提到“上基站充电30分钟”用于深度亏电开机场景",
      "verdict": "supported",
      "evidence_index": [3],
      "reason": "片段[3]步骤1写明‘上基站充电30分钟’且用于深度亏电开机"
    },
    {
      "claim": "片段步骤3提及“确认机器充电极片与基站弹片贴合，指示灯亮起表示充电正常”",
      "verdict": "supported",
      "evidence_index": [3],
      "reason": "片段[3]步骤3原文完全一致"
    }
  ]
}

{
  "claims": [
    {
      "claim": "针对“运行噪音很大有异响”问题，适用资料为[1]；其明确标注适用问题为“RC-M500 清扫噪音异常排查”，常见表现即为“运行噪音很大有异响”。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "说明书中该片段标题即为“RC-M500 清扫噪音异常排查”，常见表现为“运行噪音很大有异响”，与论断一致。"
    },
    {
      "claim": "按顺序执行以下步骤，任一步骤解决后即可结束排查。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "该指示与[1]中开头“按顺序执行以下步骤，任一步骤解决后即可结束排查”一致。"
    },
    {
      "claim": "步骤1：关机后清理边刷和滚刷缠绕的毛发，检查滚刷浮动框架是否卡异物。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "该步骤与[1]中步骤1内容逐字一致。"
    },
    {
      "claim": "步骤2：确认两块旋转拖布支架安装到位，拖布脱落偏心旋转会产生异响。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "该步骤与[1]中步骤2内容逐字一致。"
    },
    {
      "claim": "步骤3前半：若噪音只在回洗或集尘时出现，属基站风机与水泵正常工作音。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "该判断与[1]中步骤3前半句一致。"
    },
    {
      "claim": "步骤3后半：音量突然增大请联系售后。",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "“请联系售后”属于兜底建议，非事实性内容。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在的，请停止自助排查并联系官方售后。",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "结尾的兜底话术，属于非事实性建议。"
    }
  ]
}
